export type BuiltInIconKey = (typeof BUILT_IN_ICONS)[number]['key'];
export type IconValue = ICONS | BuiltInIconKey;
export const MAX_COMPOSED_ICONS = 4;

export const REPLACED_ICON_KEYS = {
  'builtin:cocaine-powder': 'builtin:cocaine',
  'builtin:construction-safety': 'builtin:synthetische-drugsproductie-locatie',
  'builtin:financial-investigation': 'builtin:finance-check',
  'builtin:materials-check': 'builtin:document-check',
  'builtin:nature-monitoring': 'builtin:illegale-dumping-chemisch-afval-herstel',
  'builtin:phishing-protection': 'builtin:online-safety',
  'builtin:vehicle-export': 'builtin:voertuigdiefstal-export-diefstal',
  'builtin:victim-support': 'builtin:safe-work',
  'builtin:worker-protection': 'builtin:safe-work',
} as const satisfies Record<string, BuiltInIconKey>;

export const currentIconValue = (icon: IconValue): IconValue =>
  typeof icon === 'string' && icon in REPLACED_ICON_KEYS
    ? REPLACED_ICON_KEYS[icon as keyof typeof REPLACED_ICON_KEYS]
    : icon;

export const isBuiltInIconKey = (icon: unknown): icon is BuiltInIconKey =>
  typeof icon === 'string' && BUILT_IN_ICONS.some(({ key }) => key === icon);

export const resolveIconSource = (icon?: IconValue, uploadedImage?: string): string | undefined => {
  if (icon === ICONS.OTHER) return uploadedImage;
  if (typeof icon === 'string') {
    const builtIn = BUILT_IN_ICONS.find(({ key }) => key === currentIconValue(icon));
    return builtIn ? `icons/${builtIn.file}` : undefined;
  }
  return IconOpts.find(({ id }) => id === icon)?.img;
};

export const resolveIconSources = (
  icons: IconValue[] | undefined,
  legacyIcon?: IconValue,
  uploadedImage?: string
): string[] => {
  const selectedIcons = icons?.length ? icons : legacyIcon !== undefined ? [legacyIcon] : [];
  return selectedIcons
    .slice(0, MAX_COMPOSED_ICONS)
    .map((icon) => resolveIconSource(icon, uploadedImage))
    .filter((source): source is string => Boolean(source));
};

